interface Run {
  code: number;
  out: string;
  err: string;
  calls: string[][];
}

async function run(argv: string[], io: Partial<IO> = {}): Promise<Run> {
  const out: string[] = [];
  const err: string[] = [];
  const calls: string[][] = [];
  const code = await main(argv, {
    out: (s) => out.push(s),
    err: (s) => err.push(s),
    home: "/nonexistent-home",
    env: {},
    run: async (cmd, args) => {
      calls.push([cmd, ...args]);
      return { code: 0, stdout: "", stderr: "" };
    },
    fetch: globalThis.fetch,
    ...io,
  });
  return { code, out: out.join("\n"), err: err.join("\n"), calls };
}

/** Flags for the command's required params, with valid values of their types. */
function requiredFlags(c: Command): string[] {
  return c.params.filter((p) => p.required).flatMap((p) => {
    if (p.type === "boolean") return [`--${p.name}`];
    const v = p.enum?.[0] ?? (p.type === "string" ? "abc" : "1");
    return [`--${p.name}`, v];
  });
}

test("help, version and the endpoint list", async () => {
  assert.match((await run([])).out, /Usage:/);
  assert.equal((await run(["--version"])).out, VERSION);
  const list = await run(["endpoints"]);
  for (const c of COMMANDS) assert.ok(list.out.includes(`socialtap ${c.platform} ${c.name.replaceAll("_", "-")}`), c.endpoint);
  assert.equal((await run(["nope"])).code, 2);
});

test("an endpoint command calls the API and prints data and meta", async (t) => {
  const mock = await MockServer.start();
  t.after(() => mock.close());
  const cmd = COMMANDS.find((c) => c.kind === "get")!;
  mock.reply({ body: { data: { id: "1" }, meta: { request_id: "req_1" } } });
  const r = await run([cmd.platform, cmd.name, ...requiredFlags(cmd), "--api-key", "st_live_cli", "--base-url", mock.url]);
  assert.equal(r.code, 0, r.err);
  assert.deepEqual(JSON.parse(r.out), { data: { id: "1" }, meta: { request_id: "req_1" } });
  const req = mock.requests[0]!;
  assert.equal(req.headers["x-api-key"], "st_live_cli");
  for (const p of cmd.params.filter((x) => x.required && x.type !== "boolean")) assert.ok(req.query.has(p.name), p.name);

  // The key also comes from the environment; a missing required param or a bad number is a usage error.
  mock.reply({ body: { data: {}, meta: {} } });
  assert.equal((await run([cmd.platform, cmd.name, ...requiredFlags(cmd), "--base-url", mock.url], { env: { [API_KEY_ENV]: "st_live_env" } })).code, 0);
  assert.equal(mock.requests[1]!.headers["x-api-key"], "st_live_env");
  if (cmd.params.some((p) => p.required)) assert.equal((await run([cmd.platform, cmd.name, "--api-key", "k"])).code, 2);
  const num = cmd.params.find((p) => p.type === "integer" || p.type === "number");
  if (num) assert.equal((await run([cmd.platform, cmd.name, ...requiredFlags(cmd), `--${num.name}`, "x", "--api-key", "k"])).code, 2);
  assert.match((await run([cmd.platform, cmd.name, "--help"])).out, /Params:/);
});

test("API errors are JSON on stderr with exit code 1", async (t) => {
  const mock = await MockServer.start();
  t.after(() => mock.close());
  const cmd = COMMANDS[0]!;
  mock.reply({ status: 404, body: { error: { code: "not_found", message: "gone", request_id: "req_e", retryable: false } } });
  const r = await run([cmd.platform, cmd.name, ...requiredFlags(cmd), "--api-key", "k", "--base-url", mock.url]);
  assert.equal(r.code, 1);
  assert.equal(JSON.parse(r.err).error.code, "not_found");
});

test("a list command walks every page with --all: one item per line", async (t) => {
  const cmd = COMMANDS.find((c) => c.kind === "list");
  if (!cmd) return;
  const mock = await MockServer.start();
  t.after(() => mock.close());
  const meta = { request_id: "r" };
  mock.reply(
    { body: { data: [{ n: 1 }, { n: 2 }], page: { has_more: true, next_cursor: "c2", next_cursor_expires_at: null }, meta } },
    { body: { data: [{ n: 3 }], page: { has_more: false, next_cursor: null, next_cursor_expires_at: null }, meta } },
  );
  const r = await run([cmd.platform, cmd.name, ...requiredFlags(cmd), "--all", "--max-pages", "5", "--api-key", "k", "--base-url", mock.url]);
  assert.equal(r.code, 0, r.err);
  assert.deepEqual(r.out.split("\n").map((l) => JSON.parse(l)), [{ n: 1 }, { n: 2 }, { n: 3 }]);
  assert.equal(JSON.parse(r.err).pages, 2);
  assert.equal(mock.requests[1]!.query.get("cursor"), "c2");
});

test("the tool command calls a tool and prints its result", async (t) => {
  const mock = await MockServer.start();
  t.after(() => mock.close());
  const tool = TOOLS[0]!;
  mock.reply({ body: { jsonrpc: "2.0", id: 1, result: { content: [{ type: "text", text: '{"results":[]}' }] } } });
  const r = await run(["tool", tool.name, '{"query":"x"}', "--api-key", "k", "--base-url", mock.url]);
  assert.equal(r.code, 0, r.err);
  assert.deepEqual(JSON.parse(r.out), { results: [] });
  assert.equal(JSON.parse(mock.requests[0]!.body).params.name, tool.name);
  assert.equal((await run(["tool", tool.name, "not json", "--api-key", "k"])).code, 2);
  assert.ok((await run(["tool"])).out.includes(tool.name));
});

test("setTomlTable replaces a table and its sub-tables, keeping the rest", () => {
  const before = 'model = "x"\n\n[mcp_servers.socialtap]\nurl = "old"\n\n[mcp_servers.socialtap.env]\nA = "1"\n\n[mcp_servers.other]\nurl = "keep"\n';
  const after = setTomlTable(before, "mcp_servers.socialtap", ["[mcp_servers.socialtap]", 'url = "new"']);
  assert.equal(after, 'model = "x"\n\n[mcp_servers.other]\nurl = "keep"\n\n[mcp_servers.socialtap]\nurl = "new"\n');
  assert.equal(setTomlTable("", "a", ["[a]", "x = 1"]), "[a]\nx = 1\n");
});

test("init installs the site's skill and registers the MCP server in every agent found", async (t) => {
  if (SKILLS_INDEX_PATH === null || MCP_PATH === null) return;
  const home = await mkdtemp(join(tmpdir(), "socialtap-init-"));
  t.after(() => rm(home, { recursive: true, force: true }));
  for (const d of [".claude", ".codex", ".cursor", ".gemini"]) await mkdir(join(home, d));
  await writeFile(join(home, ".codex", "config.toml"), 'model = "o"\n');
  await writeFile(join(home, ".cursor", "mcp.json"), JSON.stringify({ mcpServers: { other: { url: "https://o" } } }));
  await writeFile(join(home, ".gemini", "settings.json"), JSON.stringify({ theme: "dark" }));

  const skill = "---\nname: socialtap\ndescription: test\n---\n# Skill\n";
  const index = { skills: [{ name: "socialtap", type: "skill-md", url: "socialtap/SKILL.md", digest: `sha256:${createHash("sha256").update(skill).digest("hex")}` }] };
  const mock = await MockServer.start();
  t.after(() => mock.close());
  const serve = () => mock.reply({ body: index }, { text: skill });

  serve();
  const r = await run(["init", "--api-key", "st_live_key", "--base-url", mock.url], { home });
  assert.equal(r.code, 0, r.out + r.err);
  assert.equal(mock.requests[0]!.path, SKILLS_INDEX_PATH);
  for (const dir of [".claude/skills", ".agents/skills"]) assert.equal(await readFile(join(home, dir, "socialtap", "SKILL.md"), "utf8"), skill);

  const url = mock.url + MCP_PATH;
  const add = r.calls.find((c) => c[0] === "claude" && c[2] === "add-json")!;
  assert.deepEqual(add.slice(0, 6), ["claude", "mcp", "add-json", "--scope", "user", MCP_SERVER_NAME]);
  assert.deepEqual(JSON.parse(add[6]!), { type: "http", url, headers: { Authorization: "Bearer st_live_key" } });
  const toml = await readFile(join(home, ".codex", "config.toml"), "utf8");
  assert.ok(toml.startsWith('model = "o"\n'));
  assert.ok(toml.includes(`[mcp_servers.${MCP_SERVER_NAME}]\nurl = "${url}"\nhttp_headers = { "Authorization" = "Bearer st_live_key" }\n`));
  const cursor = JSON.parse(await readFile(join(home, ".cursor", "mcp.json"), "utf8"));
  assert.deepEqual(cursor.mcpServers, { other: { url: "https://o" }, [MCP_SERVER_NAME]: { url, headers: { Authorization: "Bearer st_live_key" } } });
  const gemini = JSON.parse(await readFile(join(home, ".gemini", "settings.json"), "utf8"));
  assert.deepEqual(gemini, { theme: "dark", mcpServers: { [MCP_SERVER_NAME]: { httpUrl: url, headers: { Authorization: "Bearer st_live_key" } } } });

  // Again: the same result (one table, one entry), no duplicates.
  serve();
  assert.equal((await run(["init", "--api-key", "st_live_key", "--base-url", mock.url], { home })).code, 0);
  assert.equal((await readFile(join(home, ".codex", "config.toml"), "utf8")).split(`[mcp_servers.${MCP_SERVER_NAME}]`).length, 2);
});

test("init: a key in a config is the user's alone and said out loud; Claude Code at a terminal prefers the browser to the environment's", async (t) => {
  const mock = await MockServer.start();
  const home = await mkdtemp(join(tmpdir(), "socialtap-init-"));
  t.after(() => rm(home, { recursive: true, force: true }));
  t.after(() => mock.close());
  for (const d of [".claude", ".cursor"]) await mkdir(join(home, d));
  const cursor = join(home, ".cursor", "mcp.json");
  await writeFile(cursor, "{}", { mode: 0o644 });
  const index = { skills: [{ name: "s", type: "skill-md", url: "/s.md" }] };
  const init = (io: Partial<IO>) => {
    mock.reply({ body: index }, { text: "# s\n" });
    return run(["init", "--base-url", mock.url], { home, ...io });
  };
  const claudeHeaders = (r: Run) => JSON.parse(r.calls.find((c) => c[2] === "add-json")![6]!).headers;

  const env = { [API_KEY_ENV]: "st_live_env" };
  let r = await init({ env, interactive: true });
  assert.equal(r.code, 0, r.out + r.err);
  assert.equal(claudeHeaders(r), undefined, "the browser, not the environment's key");
  assert.ok(r.out.includes(`stored your API key in ${cursor}`));
  assert.equal((await stat(cursor)).mode & 0o777, 0o600);
  assert.deepEqual(JSON.parse(await readFile(cursor, "utf8")).mcpServers[MCP_SERVER_NAME].headers, { Authorization: "Bearer st_live_env" });

  // Nobody to sign in, or an entry that sends a key today: the key, as asked, and said.
  r = await init({ env });
  assert.deepEqual(claudeHeaders(r), { Authorization: "Bearer st_live_env" });
  assert.ok(r.out.includes(`stored your API key in ${join(home, ".claude.json")}`));
  await writeFile(join(home, ".claude.json"), JSON.stringify({ mcpServers: { [MCP_SERVER_NAME]: { headers: { Authorization: "Bearer old" } } } }), { mode: 0o644 });
  r = await init({ env, interactive: true });
  assert.deepEqual(claudeHeaders(r), { Authorization: "Bearer st_live_env" });
  assert.equal((await stat(join(home, ".claude.json"))).mode & 0o777, 0o600);
});

test("init without a key registers the server for the browser's sign-in; a bad digest or no agent fails", async (t) => {
  if (SKILLS_INDEX_PATH === null || MCP_PATH === null) return;
  const home = await mkdtemp(join(tmpdir(), "socialtap-init-"));
  t.after(() => rm(home, { recursive: true, force: true }));
  await mkdir(join(home, ".cursor"));
  const mock = await MockServer.start();
  t.after(() => mock.close());
  mock.reply({ body: { skills: [{ name: "socialtap", type: "skill-md", url: "s/SKILL.md" }] } }, { text: "# s\n" });
  const r = await run(["init", "--base-url", mock.url], { home });
  assert.equal(r.code, 0, r.out);
  assert.match(r.out, /No API key given/);
  assert.equal(await readFile(join(home, ".agents", "skills", "socialtap", "SKILL.md"), "utf8"), "# s\n");
  const cursor = JSON.parse(await readFile(join(home, ".cursor", "mcp.json"), "utf8"));
  assert.deepEqual(cursor.mcpServers, { [MCP_SERVER_NAME]: { url: mock.url + MCP_PATH } });

  mock.reply({ body: { skills: [{ name: "socialtap", type: "skill-md", url: "s/SKILL.md", digest: "sha256:00" }] } }, { text: "# s\n" });
  assert.equal((await run(["init", "--base-url", mock.url], { home })).code, 1);
  assert.equal((await run(["init"], { home: join(home, "empty") })).code, 2);
  assert.equal((await run(["init", "--agent", "vim"], { home })).code, 2);
});
